notice.body:
{{ header }}
<div class="bb-main-content"><table class="bb-box" cellpadding="0" cellspacing="0"><tr><td class="bb-content"><h2>New contact message</h2><p><strong>Name:</strong> {{ contact_name }}</p><p><strong>Email:</strong> {{ contact_email }}</p><p><strong>Phone:</strong> {{ contact_phone }}</p><p><strong>Subject:</strong> {{ contact_subject }}</p><p>{{ contact_content }}</p><p>{{ contact_custom_fields }}</p></td></tr></table></div>
{{ footer }}

sender-confirmation.body:
{{ header }}
<div class="bb-main-content"><table class="bb-box" cellpadding="0" cellspacing="0"><tr><td class="bb-content"><h2>Thank you, {{ contact_name }}</h2><p>We received your message and will respond soon.</p><p>{{ contact_content }}</p></td></tr></table></div>
{{ footer }}
